// Some portions generated by Codex

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const vm = require('node:vm');
const { spawnSync } = require('node:child_process');

const appSource = path.resolve(__dirname,
    '../../tools/workbench/src/main/webapp/scripts/ts/workbenchApp.ts');

function loadWorkbenchWithFailedEarlyThemeScript() {
    const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'rdf4j-workbench-script-retry-'));
    const output = path.join(directory, 'workbench.js');
    const compilation = spawnSync('tsc', [
        '--noImplicitAny',
        '--target', 'ES2017',
        '--lib', 'ES2017,DOM',
        '--skipLibCheck',
        '--outFile', output,
        appSource
    ], { encoding: 'utf8' });
    assert.equal(compilation.status, 0,
        `Workbench source must compile for script-retry contract:\n${compilation.stdout}${compilation.stderr}`);

    const appendedScripts = [];
    const earlyThemeScript = {
        src: '/rdf4j-workbench/scripts/workbench-theme.js',
        getAttribute(name) { return name === 'src' ? this.src : null; },
        setAttribute() {}
    };
    const document = {
        readyState: 'loading',
        addEventListener() {},
        getElementById() { return null; },
        querySelector(selector) {
            if (selector.includes('/scripts/workbench-theme.js"]')) {
                return earlyThemeScript;
            }
            const source = selector.match(/^script\[src="(.*)"\]$/);
            return source && appendedScripts.find(script => script.src === source[1]) || null;
        },
        createElement(name) {
            assert.equal(name, 'script');
            const attributes = {};
            return {
                async: true,
                onload: null,
                onerror: null,
                src: '',
                getAttribute(attribute) { return attributes[attribute] || null; },
                setAttribute(attribute, value) { attributes[attribute] = value; },
                handlersInstalledAtAppend: false
            };
        },
        head: {
            appendChild(script) {
                script.handlersInstalledAtAppend = typeof script.onload === 'function'
                    && typeof script.onerror === 'function';
                appendedScripts.push(script);
                script.setAttribute('data-workbench-loaded', 'true');
                script.onload();
                return script;
            }
        }
    };
    const window = { document };
    const workbench = {};
    const context = vm.createContext({ console, URL, Promise, window, workbench, setTimeout });
    vm.runInContext(fs.readFileSync(output, 'utf8'), context, { filename: output });
    workbench.views = { render() {} };
    workbench.queryStream = {
        createRowStore() {},
        consumeNdjsonResponse() {},
        scheduleRowStoreMaintenance() {}
    };
    return { appendedScripts, earlyThemeScript, workbench };
}

test('shared runtime retries an early theme script after its load error has passed', async () => {
    const { appendedScripts, earlyThemeScript, workbench } = loadWorkbenchWithFailedEarlyThemeScript();
    const mount = {
        getAttribute() { return ''; },
        setAttribute() {}
    };
    const boot = workbench.app.bootstrap(mount).then(result => result, error => error);

    await new Promise(setImmediate);

    const retry = appendedScripts.find(script => script.src.endsWith('/scripts/workbench-theme.js'));
    assert.ok(retry, 'the loader should issue a fresh request instead of waiting on the old error event');
    assert.notEqual(retry, earlyThemeScript);
    assert.equal(retry.handlersInstalledAtAppend, true,
        'the retry must install success and error handlers before it is appended');
    const result = await boot;
    assert.equal(result.status, 'skipped');
});
